create function workspace_private.editor_recovery_validate(p_value jsonb,p_schema jsonb,p_depth integer default 0) returns void
language plpgsql immutable set search_path='' as $fn$
declare child jsonb; entry record; valid boolean:=false; width integer; n numeric;
begin
 if p_depth>18 or p_value is null or p_schema is null then raise exception 'Invalid editor draft structure.' using errcode='22023'; end if;
 if p_schema ? 'anyOf' then
  for child in select * from jsonb_array_elements(p_schema->'anyOf') loop
   begin perform workspace_private.editor_recovery_validate(p_value,child,p_depth+1);valid:=true;exit;
   exception when sqlstate '22023' then null;end;
  end loop;
  if not valid then raise exception 'Invalid editor draft value.' using errcode='22023';end if;
  return;
 end if;
 if jsonb_typeof(p_value) is distinct from (case when p_schema->>'type'='integer' then 'number' else p_schema->>'type' end)
 or (p_schema ? 'const' and p_value<>p_schema->'const')
 or (p_schema ? 'enum' and not exists(select 1 from jsonb_array_elements(p_schema->'enum') e where e=p_value)) then
  raise exception 'Invalid editor draft field.' using errcode='22023';
 end if;
 if p_schema->>'type'='object' then
  if exists(select 1 from jsonb_object_keys(p_value) k where not(p_schema->'properties' ? k))
  or exists(select 1 from jsonb_array_elements_text(p_schema->'required') k where not(p_value ? k)) then
   raise exception 'Unknown or missing editor draft field.' using errcode='22023';
  end if;
  for entry in select * from jsonb_each(p_value) loop perform workspace_private.editor_recovery_validate(entry.value,p_schema->'properties'->entry.key,p_depth+1);end loop;
 elsif p_schema->>'type'='array' then
  if jsonb_array_length(p_value)>coalesce((p_schema->>'maxItems')::int,1000) then raise exception 'Editor draft list is too long.' using errcode='22023';end if;
  for child in select * from jsonb_array_elements(p_value) loop perform workspace_private.editor_recovery_validate(child,p_schema->'items',p_depth+1);end loop;
 elsif p_schema->>'type'='string' then
  width:=char_length(p_value#>>'{}')+char_length(regexp_replace(p_value#>>'{}',U&'[\0001-\FFFF]','','g'));
  if width>coalesce((p_schema->>'maxLength')::int,256) then raise exception 'Editor draft text is too long.' using errcode='22023';end if;
 elsif p_schema->>'type' in ('number','integer') then
  n:=(p_value#>>'{}')::numeric;
  if (p_schema->>'type'='integer' and n<>trunc(n)) or n< -9007199254740991 or n>coalesce((p_schema->>'maximum')::numeric,9007199254740991) then
   raise exception 'Editor draft number is outside its bounds.' using errcode='22023';
  end if;
 end if;
end;$fn$;

create function workspace_private.require_editor_target(p_target jsonb) returns uuid
language plpgsql stable security definer set search_path='' as $fn$
declare target uuid; domain text:=p_target->>'domain';kind text:=p_target->>'kind';doc uuid;found_doc uuid;
begin
 if not workspace_private.is_direct_session() or auth.jwt()->>'client_id' is not null then
  raise exception 'Working drafts are private to the native owner editor.' using errcode='42501';
 end if;
 if p_target is null or jsonb_typeof(p_target)<>'object' or not(p_target ?& array['domain','kind','documentId'])
 or (p_target-array['domain','kind','documentId'])<>'{}'::jsonb
 or jsonb_typeof(p_target->'domain')<>'string' or jsonb_typeof(p_target->'kind')<>'string'
 or workspace_private.editor_recovery_schema(domain,kind) is null then raise exception 'Choose an admitted editor target.' using errcode='22023';end if;
 if p_target->'documentId'<>'null'::jsonb then
  if jsonb_typeof(p_target->'documentId')<>'string' or (p_target->>'documentId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
   raise exception 'Choose an admitted editor target.' using errcode='22023';
  end if;
  doc:=(p_target->>'documentId')::uuid;
 end if;
 target:=case domain when 'ministry' then workspace_private.require_ministry(kind,true)
 when 'nonprofit' then workspace_private.require_nonprofit(kind)
 when 'investor' then workspace_private.require_investor(kind)
 when 'executive' then workspace_private.require_executive(kind) end;
 if doc is not null then
  execute format('select id from workspace_private.%I where workspace_id=$1 and kind=$2 and id=$3',domain||'_documents')
  into found_doc using target,kind,doc;
  if found_doc is null then raise exception 'Editor record unavailable.' using errcode='P0002';end if;
 end if;
 return target;
end;$fn$;

create function workspace_private.editor_source_revision(p_workspace uuid,p_target jsonb) returns integer
language plpgsql stable security definer set search_path='' as $fn$
declare revision integer;
begin
 if p_target->>'documentId' is null and not(p_target->>'domain'='ministry' and p_target->>'kind'='profile') then return 0;end if;
 execute format('select revision from workspace_private.%I where workspace_id=$1 and kind=$2 and ($3 is null or id=$3)',p_target->>'domain'||'_documents')
 into revision using p_workspace,p_target->>'kind',(p_target->>'documentId')::uuid;
 return coalesce(revision,0);
end;$fn$;

create table workspace_private.ministry_editor_drafts(
 workspace_id uuid not null references workspace.workspaces(id) on delete cascade,
 kind text not null check(kind in ('profile','research','archive')),slot text not null,document_id uuid,
 version integer not null check(version>0),schema_version integer not null default 1 check(schema_version=1),
 base_revision integer,values_json jsonb,saved_at timestamptz not null default now(),receipt jsonb not null,
 primary key(workspace_id,kind,slot),
 foreign key(workspace_id,document_id) references workspace_private.ministry_documents(workspace_id,id) on delete cascade,
 check(slot=coalesce(document_id::text,'new')),
 check((values_json is null and base_revision is null) or (values_json is not null and base_revision>=0))
);
create table workspace_private.ministry_editor_draft_receipts(
 workspace_id uuid not null references workspace.workspaces(id) on delete cascade,request_id uuid not null,
 input_hash text not null check(length(input_hash)=64),kind text not null,slot text not null,receipt jsonb not null,
 created_at timestamptz not null default now(),primary key(workspace_id,request_id),
 foreign key(workspace_id,kind,slot) references workspace_private.ministry_editor_drafts(workspace_id,kind,slot) on delete cascade
);
alter table workspace_private.ministry_editor_drafts enable row level security;
alter table workspace_private.ministry_editor_draft_receipts enable row level security;
revoke all on workspace_private.ministry_editor_drafts,workspace_private.ministry_editor_draft_receipts from public,anon,authenticated;

