create function workspace_private.editor_draft_snapshot(p_workspace uuid,p_target jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $fn$
declare d jsonb;
begin
 execute format('select to_jsonb(x) from workspace_private.%I x where workspace_id=$1 and kind=$2 and slot=$3',p_target->>'domain'||'_editor_drafts')
 into d using p_workspace,p_target->>'kind',coalesce(((p_target->>'documentId')::uuid)::text,'new');
 return jsonb_build_object('target',p_target,'schemaVersion',1,'version',coalesce((d->>'version')::int,0),
 'baseRevision',d->'base_revision','currentRevision',workspace_private.editor_source_revision(p_workspace,p_target),
 'values',d->'values_json','savedAt',d->'saved_at','receipt',d->'receipt');
end;$fn$;

create function workspace.native_editor_draft(p_target jsonb) returns jsonb
language plpgsql stable security definer set search_path='' as $fn$
declare target uuid:=workspace_private.require_editor_target(p_target);
begin return workspace_private.editor_draft_snapshot(target,p_target);end;$fn$;

create function workspace.native_change_editor_draft(p_change jsonb) returns jsonb
language plpgsql security definer set search_path='' as $fn$
declare p_target jsonb:=p_change->'target';target uuid:=workspace_private.require_editor_target(p_target);
 domain text:=p_target->>'domain';kind text:=p_target->>'kind';doc uuid:=(p_target->>'documentId')::uuid;
 slot text:=coalesce(doc::text,'new');operation text:=p_change->>'operation';request_id uuid;expected_version integer;
 d jsonb;existing_receipt jsonb;fingerprint text;version integer;source_revision integer;base_revision integer;
 draft_values jsonb;receipt jsonb;committed_id uuid;committed_revision integer;result jsonb;canonical_data jsonb;
begin
 if p_change is null or jsonb_typeof(p_change)<>'object'
 or operation is null or operation not in ('save','discard','commit')
 or not(p_change ?& array['target','operation','requestId','expectedVersion'])
 or jsonb_typeof(p_change->'requestId')<>'string' or (p_change->>'requestId')!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
 or jsonb_typeof(p_change->'expectedVersion')<>'number' or (p_change->>'expectedVersion')!~'^(0|[1-9][0-9]{0,9})$'
 or (p_change->>'expectedVersion')::numeric>2147483646
 or octet_length(p_change::text)>650000 then raise exception 'Invalid editor draft request.' using errcode='22023';end if;
 request_id:=(p_change->>'requestId')::uuid;expected_version:=(p_change->>'expectedVersion')::int;
 if operation='save' then
  if (p_change-array['target','operation','requestId','expectedVersion','schemaVersion','baseRevision','values'])<>'{}'::jsonb
  or p_change->'schemaVersion' is distinct from '1'::jsonb or not(p_change ?& array['baseRevision','values'])
  or jsonb_typeof(p_change->'baseRevision')<>'number' or (p_change->>'baseRevision')!~'^(0|[1-9][0-9]{0,9})$'
  or (p_change->>'baseRevision')::numeric>2147483646 then raise exception 'Invalid editor draft request.' using errcode='22023';end if;
  base_revision:=(p_change->>'baseRevision')::int;draft_values:=p_change->'values';
  if jsonb_typeof(draft_values)<>'object' or not(draft_values ?& array['data','ui']) or (draft_values-array['data','ui'])<>'{}'::jsonb then
   raise exception 'Invalid editor draft values.' using errcode='22023';end if;
  perform workspace_private.editor_recovery_validate(draft_values->'data',workspace_private.editor_recovery_schema(domain,kind));
  perform workspace_private.editor_recovery_validate(draft_values->'ui',
   '{"type":"object","properties":{"unsetProfile":{"type":"boolean"},"meetingTime":{"type":"object","properties":{"local":{"type":"string","maxLength":40},"selection":{"type":"string","maxLength":64},"pending":{"type":"boolean"}},"required":["local","selection","pending"],"additionalProperties":false},"availability":{"type":"object","properties":{"zone":{"type":"string","maxLength":100},"offered":{"type":"array","maxItems":20,"items":{"type":"object","properties":{"id":{"type":"string","maxLength":36},"start":{"type":"string","maxLength":40},"end":{"type":"string","maxLength":40},"startInstant":{"type":"string","maxLength":64},"endInstant":{"type":"string","maxLength":64}},"required":["id","start","end","startInstant","endInstant"],"additionalProperties":false}},"available":{"type":"array","maxItems":20,"items":{"type":"object","properties":{"id":{"type":"string","maxLength":36},"start":{"type":"string","maxLength":40},"end":{"type":"string","maxLength":40},"startInstant":{"type":"string","maxLength":64},"endInstant":{"type":"string","maxLength":64}},"required":["id","start","end","startInstant","endInstant"],"additionalProperties":false}},"busy":{"type":"array","maxItems":200,"items":{"type":"object","properties":{"id":{"type":"string","maxLength":36},"start":{"type":"string","maxLength":40},"end":{"type":"string","maxLength":40},"startInstant":{"type":"string","maxLength":64},"endInstant":{"type":"string","maxLength":64}},"required":["id","start","end","startInstant","endInstant"],"additionalProperties":false}},"source":{"type":"string","maxLength":240},"bufferMinutes":{"type":"integer","maximum":120},"checkedAt":{"anyOf":[{"type":"string","maxLength":64},{"type":"null"}]},"context":{"type":"string","maxLength":20000},"pending":{"type":"boolean"}},"required":["zone","offered","available","busy","source","bufferMinutes","checkedAt","context","pending"],"additionalProperties":false}},"required":[],"additionalProperties":false}'::jsonb);
  if (draft_values->'ui' ? 'unsetProfile' and not(domain='ministry' and kind='profile'))
  or (draft_values->'ui' ? 'meetingTime' and not(domain='executive' and kind='meeting'))
  or (draft_values->'ui' ? 'availability' and not(domain='executive' and kind='meeting'))
  or exists(select 1 from jsonb_array_elements(coalesce(draft_values->'ui'->'availability'->'offered','[]'::jsonb)
      ||coalesce(draft_values->'ui'->'availability'->'available','[]'::jsonb)
      ||coalesce(draft_values->'ui'->'availability'->'busy','[]'::jsonb)) x
    where x->>'id'!~*'^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
  then raise exception 'Editor state does not match this record type.' using errcode='22023';end if;
 elsif operation='commit' then
  if (p_change-array['target','operation','requestId','expectedVersion','confirm'])<>'{}'::jsonb or p_change->'confirm' is distinct from 'true'::jsonb then
   raise exception 'Confirm the exact recovered draft before saving.' using errcode='22023';end if;
 elsif (p_change-array['target','operation','requestId','expectedVersion'])<>'{}'::jsonb then
  raise exception 'Invalid editor draft request.' using errcode='22023';
 end if;
 -- The same lock as canonical domain saves, always acquired before a draft row.
 -- A canonical save and retirement of its draft are one transaction.
 perform pg_advisory_xact_lock(hashtextextended(target::text||':'||domain,0));
 perform workspace_private.require_editor_target(p_target);
 source_revision:=workspace_private.editor_source_revision(target,p_target);
 execute format('select to_jsonb(x) from workspace_private.%I x where workspace_id=$1 and kind=$2 and slot=$3 for update',domain||'_editor_drafts')
 into d using target,kind,slot;
 version:=coalesce((d->>'version')::int,0);
 fingerprint:=encode(extensions.digest(p_change::text,'sha256'),'hex');
 execute format('select to_jsonb(x) from workspace_private.%I x where workspace_id=$1 and request_id=$2',domain||'_editor_draft_receipts')
 into existing_receipt using target,request_id;
 if existing_receipt is not null then
  if existing_receipt->>'input_hash'<>fingerprint or existing_receipt->>'kind'<>kind or existing_receipt->>'slot'<>slot then
   raise exception 'This draft request was already used.' using errcode='40001';end if;
  if (existing_receipt->'receipt'->>'version')::int<>version then
   raise exception 'This working draft changed. Review the latest draft before continuing.' using errcode='40001';end if;
  if operation='commit' then
   execute format('select revision from workspace_private.%I where workspace_id=$1 and kind=$2 and id=$3',domain||'_documents')
   into committed_revision using target,kind,(existing_receipt->'receipt'->>'committedDocumentId')::uuid;
   if committed_revision is distinct from (existing_receipt->'receipt'->>'committedRevision')::int then
    raise exception 'The saved record changed. Open its latest revision.' using errcode='40001';end if;
  end if;
  return workspace_private.editor_draft_snapshot(target,p_target);
 end if;
 if version<>expected_version then raise exception 'This working draft changed. Review the latest draft before continuing.' using errcode='40001';end if;
 if operation='save' then
  if base_revision>source_revision or (doc is not null and base_revision<1) or (doc is null and base_revision<>0) then
   raise exception 'Invalid editor draft base revision.' using errcode='22023';end if;
 elsif operation='commit' then
  if d->'values_json' is null or d->'values_json'='null'::jsonb then raise exception 'Save a working draft before confirming it.' using errcode='22023';end if;
  if (d->>'base_revision')::int<>source_revision then raise exception 'The source record changed. Compare it before confirming this draft.' using errcode='40001';end if;
  draft_values:=d->'values_json';
  if draft_values->'ui'->'meetingTime'->'pending'='true'::jsonb or draft_values->'ui'->'availability'->'pending'='true'::jsonb then
   raise exception 'Apply or discard unfinished meeting planning before saving.' using errcode='22023';end if;
  canonical_data:=case when draft_values->'ui'->'unsetProfile'='true'::jsonb then null else draft_values->'data' end;
  result:=case domain
   when 'ministry' then workspace.ministry_save_document(kind,doc,source_revision,request_id,canonical_data,true)
   when 'nonprofit' then workspace.nonprofit_save_document(kind,doc,source_revision,request_id,canonical_data,true)
   when 'investor' then workspace.investor_save_document(kind,doc,source_revision,request_id,canonical_data,true)
   when 'executive' then workspace.executive_save_document(kind,doc,source_revision,request_id,canonical_data,true) end;
  committed_id:=(result->'document'->>'id')::uuid;committed_revision:=(result->'document'->>'revision')::int;
  if committed_id is null or committed_revision is null then raise exception 'Saved record could not be verified.' using errcode='40001';end if;
 end if;
 if operation<>'save' then draft_values:=null;base_revision:=null;end if;
 receipt:=jsonb_build_object('requestId',request_id,'operation',operation,'version',version+1,'committedDocumentId',committed_id,'committedRevision',committed_revision);
 execute format('insert into workspace_private.%I(workspace_id,kind,slot,document_id,version,base_revision,values_json,receipt)
 values($1,$2,$3,$4,$5,$6,$7,$8) on conflict(workspace_id,kind,slot) do update set
 version=excluded.version,base_revision=excluded.base_revision,values_json=excluded.values_json,receipt=excluded.receipt,saved_at=now()',domain||'_editor_drafts')
 using target,kind,slot,doc,version+1,base_revision,draft_values,receipt;
 -- Receipts retain only a digest and result metadata, never discarded text.
 execute format('insert into workspace_private.%I(workspace_id,request_id,input_hash,kind,slot,receipt) values($1,$2,$3,$4,$5,$6)',domain||'_editor_draft_receipts')
 using target,request_id,fingerprint,kind,slot,receipt;
 return workspace_private.editor_draft_snapshot(target,p_target);
end;$fn$;

revoke all on function workspace_private.editor_recovery_schema(text,text),workspace_private.editor_recovery_validate(jsonb,jsonb,integer),
 workspace_private.require_editor_target(jsonb),workspace_private.editor_source_revision(uuid,jsonb),workspace_private.editor_draft_snapshot(uuid,jsonb) from public,anon,authenticated;
revoke all on function workspace.native_editor_draft(jsonb),workspace.native_change_editor_draft(jsonb) from public,anon;
grant execute on function workspace.native_editor_draft(jsonb),workspace.native_change_editor_draft(jsonb) to authenticated;
notify pgrst,'reload schema';
